import{_ as a,o as t,c as i,ag as r}from"./chunks/framework.B3IQijK_.js";const m=JSON.parse('{"title":"Paper trade and monitor","description":"Find candidates, build risk-sized plans, record Office paper trades, monitor positions, and manage exits.","frontmatter":{"title":"Paper trade and monitor","description":"Find candidates, build risk-sized plans, record Office paper trades, monitor positions, and manage exits.","outline":2,"head":[["link",{"rel":"canonical","href":"https://tradecli.in/wiki/trading-office/paper-operations"}]]},"headers":[],"relativePath":"trading-office/paper-operations.md","filePath":"trading-office/paper-operations.md"}'),n={name:"trading-office/paper-operations.md"};function o(s,e,l,d,p,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="paper-trade-and-monitor" tabindex="-1">Paper trade and monitor <a class="header-anchor" href="#paper-trade-and-monitor" aria-label="Permalink to &quot;Paper trade and monitor&quot;">​</a></h1><p>Paper trading turns a researched setup into a simulated transaction in the active trading book. It joins candidate selection, deterministic risk math, a reviewable ticket, market-derived marks, planned exits, and the Office ledger.</p><p>An Office paper transaction belongs to the Trading Office ledger. It records the strategy, risk, position, and exit plan without placing a live broker order.</p><h2 id="three-ways-to-reach-a-paper-ticket" tabindex="-1">Three ways to reach a paper ticket <a class="header-anchor" href="#three-ways-to-reach-a-paper-ticket" aria-label="Permalink to &quot;Three ways to reach a paper ticket&quot;">​</a></h2><h3 id="from-a-promoted-strategy" tabindex="-1">From a promoted strategy <a class="header-anchor" href="#from-a-promoted-strategy" aria-label="Permalink to &quot;From a promoted strategy&quot;">​</a></h3><p>Open the Strategy Library:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/strategies</span></span></code></pre></div><p>An approved or active paper deployment can expose <strong>Trade</strong>. The current path creates a risk-sized, human-confirmed ticket from the stored universe, exit fields, and deployment risk limit, then tags the resulting trade with its strategy-version and deployment identifiers.</p><p>Review the generated symbol, direction, instrument, quantity, stop, targets, and risk before confirming the ticket. The resulting transaction stays connected to the strategy version and deployment that produced it.</p><h3 id="from-scanner" tabindex="-1">From Scanner <a class="header-anchor" href="#from-scanner" aria-label="Permalink to &quot;From Scanner&quot;">​</a></h3><p>Open Scanner with <code>Ctrl+Shift+N</code>. It supports a repeatable pipeline:</p><p><strong>saved scan or symbol search → candidate → strategy card → paper booking → Market Terminal</strong></p><p>Saved scans form a shared Office playbook. Re-running a saved definition applies the same validated query, while the market results can naturally change. The Scanner surface also covers equity screens, option chains, and futures curves when the required data is available.</p><h3 id="from-conversation" tabindex="-1">From conversation <a class="header-anchor" href="#from-conversation" aria-label="Permalink to &quot;From conversation&quot;">​</a></h3><p>Ask the active employee to turn a setup into a strategy plan. The deterministic planning layer can resolve:</p><ul><li>direction and entry reference;</li><li>stop as a price, percentage, or ATR-based distance;</li><li>targets as prices, percentages, or R-multiples;</li><li>equal or explicit scale-out quantities;</li><li>risk as a fixed amount or percentage of book cash;</li><li>whole-unit or whole-lot sizing;</li><li>an optional planned time exit.</li></ul><p>The result is a computed plan and risk card, not free-form AI arithmetic. Review it before opening the paper ticket.</p><h2 id="review-the-risk-card" tabindex="-1">Review the risk card <a class="header-anchor" href="#review-the-risk-card" aria-label="Permalink to &quot;Review the risk card&quot;">​</a></h2><p>Before booking, check:</p><ul><li>symbol, instrument, side, and product type;</li><li>entry reference and the source of the current mark;</li><li>quantity or lots;</li><li>stop price and risk per unit;</li><li>total paper risk and percentage of book cash;</li><li>target prices, R:R, and scale-out quantities;</li><li>planned time exit;</li><li>affordability or reward-to-risk warnings;</li><li>strategy-version and deployment tags, when this came from the library.</li></ul><p>Changing the stop, risk, quantity, or lots recomputes the plan. A manual size override also changes the implied risk shown on the card.</p><h2 id="mandate-and-risk-checks" tabindex="-1">Mandate and risk checks <a class="header-anchor" href="#mandate-and-risk-checks" aria-label="Permalink to &quot;Mandate and risk checks&quot;">​</a></h2><p>Before a paper entry is recorded, the system can block it when stored controls deny the action. Checks include paper-trade permission, kill-switch state, allowed instruments or symbols, maximum notional, required stops, and market-session rules.</p><p>Treat a warning as a reason to inspect the mandate and book state, not as permission to improvise around the control.</p><h2 id="book-the-paper-entry" tabindex="-1">Book the paper entry <a class="header-anchor" href="#book-the-paper-entry" aria-label="Permalink to &quot;Book the paper entry&quot;">​</a></h2><p>Confirming the ticket records the simulated entry and its exit plan in the local Trading Office record. The entry can carry targets, stop, scale-out quantities, and a time exit so later monitoring does not need to reconstruct the plan from chat.</p><p>When no explicit paper fill is supplied, the trade path obtains a current TradingView-derived price. If required market data is unavailable, the safe result is an error rather than an invented fill.</p><h2 id="monitor-in-market-terminal" tabindex="-1">Monitor in Market Terminal <a class="header-anchor" href="#monitor-in-market-terminal" aria-label="Permalink to &quot;Monitor in Market Terminal&quot;">​</a></h2><p>Open Market Terminal with either path:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/terminal</span></span></code></pre></div><p>or <code>Ctrl+Shift+M</code>.</p><p>The terminal shows the active Office paper book, open positions, current marks, and unrealized P&amp;L. Broker holdings can appear as read-only context when configured; they are not merged into the Office paper ledger.</p><p>Use it to:</p><ul><li>inspect entry, quantity, mark, and P&amp;L;</li><li>open a new paper entry ticket;</li><li>exit a position fully or partially;</li><li>verify that a planned exit changed the position and ledger.</li></ul><p>The conversation shortcuts <code>/trade</code> and <code>/exit [symbol]</code> route into the same paper-trade surfaces.</p><h2 id="deterministic-position-monitoring" tabindex="-1">Deterministic position monitoring <a class="header-anchor" href="#deterministic-position-monitoring" aria-label="Permalink to &quot;Deterministic position monitoring&quot;">​</a></h2><p>The position monitor is a background service for recorded exit conditions. It can evaluate:</p><ul><li>stop-loss levels;</li><li>one or more targets;</li><li>planned time exits;</li><li>applicable intraday cutoffs.</li></ul><p>It works from the stored plan and market data, not from a watch prompt. A watch can notice and report a condition; the position monitor applies the exit rules recorded on the paper position. You can inspect, partially exit, or fully exit the position yourself through Market Terminal at any time.</p><h2 id="if-a-price-or-risk-check-fails" tabindex="-1">If a price or risk check fails <a class="header-anchor" href="#if-a-price-or-risk-check-fails" aria-label="Permalink to &quot;If a price or risk check fails&quot;">​</a></h2><ul><li>A missing current price stops the entry instead of inventing a paper fill. Check the <a href="/trading-sandbox-website-preview/wiki/getting-started/tradingview-setup">TradingView connection</a>, then reopen the ticket.</li><li>A mandate denial stops the entry. Review the stored mandate in Control Center; do not work around the denied control in conversation.</li><li>A quote error does not remove the position from Market Terminal. Refresh the marks after the connected market source is available again.</li><li>Confirm the ledger and remaining quantity after every partial or full exit.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/trading-sandbox-website-preview/wiki/trading-office/strategy-lab">Test in Strategy Lab</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/watches">Automation tools</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/review">Review and improve</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/concepts">Concepts and terminology</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/commands">Commands and shortcuts</a></li></ul>',43)])])}const u=a(n,[["render",o]]);export{m as __pageData,u as default};
